import React, {
  Suspense,
  lazy,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import NodataFound from "../../assets/img/nodatafound.png";
import { getUser } from "../../context/useAuth";
import { GET } from "../../lib/request";
import { API } from "../../lib/endpoint";

const DeviceTab = lazy(() => import("./HomePageTab/Devicetab/Device"));
const AddDevice = lazy(() => import("./HomePageTab/AddDevice/AddDevice"));
const AddSiteDialog = lazy(
  () => import("./Managment/SitesMgt/AddSite/SitesAddDialog"),
);

const DASHBOARD_CACHE_KEY = "dashboard-home-cache-v2";

const readDashboardCache = () => {
  try {
    const raw = sessionStorage.getItem(DASHBOARD_CACHE_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch (error) {
    console.error("Dashboard cache parse failed:", error);
    return null;
  }
};

const writeDashboardCache = (data) => {
  try {
    sessionStorage.setItem(DASHBOARD_CACHE_KEY, JSON.stringify(data));
  } catch (error) {
    console.error("Dashboard cache write failed:", error);
  }
};

function SiteTabsSkeleton() {
  return (
    <div
      className="rounded-xl p-5 mb-6 bg-gradient-to-r from-[#0a192f] to-[#0f3057]
      shadow-lg border border-[#1f4068]"
    >
      <div className="flex justify-between items-center mb-4">
        <div className="h-7 w-24 rounded bg-white/15 animate-pulse" />
        <div className="h-9 w-28 rounded-lg bg-white/10 animate-pulse" />
      </div>
      <div className="flex gap-3 overflow-hidden">
        {Array.from({ length: 4 }).map((_, index) => (
          <div
            key={index}
            className="h-11 min-w-[160px] rounded-lg bg-white/12 animate-pulse"
          />
        ))}
      </div>
    </div>
  );
}

function DeviceSectionSkeleton() {
  return (
    <div className="bg-white rounded-xl shadow border p-5">
      <div className="flex justify-between items-center mb-5">
        <div className="h-7 w-28 rounded bg-slate-200 animate-pulse" />
        <div className="h-9 w-32 rounded-lg bg-slate-200 animate-pulse" />
      </div>
      <div className="grid gap-3">
        <div className="h-12 rounded-lg bg-slate-100 animate-pulse" />
        <div className="h-44 rounded-lg bg-slate-100 animate-pulse" />
        <div className="h-72 rounded-lg bg-slate-100 animate-pulse" />
      </div>
    </div>
  );
}

function LazyActionFallback({ label }) {
  return (
    <div className="h-9 min-w-[112px] rounded-lg bg-white/10 animate-pulse">
      <span className="sr-only">{label}</span>
    </div>
  );
}

function App() {
  const cachedDashboard = useMemo(readDashboardCache, []);
  const [value, setValue] = useState(cachedDashboard?.selectedSiteIndex ?? 0);
  const [value1, setValue1] = useState(0);
  const [sites, setSites] = useState(cachedDashboard?.sites ?? []);
  const [sitesID, setSitesID] = useState(cachedDashboard?.sitesID ?? null);
  const [selectSiteData, setSelectSiteData] = useState(
    cachedDashboard?.selectSiteData ?? null,
  );
  const [sitezero, setSiteZero] = useState(cachedDashboard?.sitezero ?? null);
  const [deviceID, setDevice] = useState(cachedDashboard?.deviceID ?? []);
  const [pagination, setPagination] = useState(
    cachedDashboard?.pagination ?? {
      page: 1,
      limit: 10,
      total: 0,
      totalPages: 1,
    },
  );
  const [sitesLoading, setSitesLoading] = useState(!cachedDashboard?.sites);
  const [devicesLoading, setDevicesLoading] = useState(
    Boolean(cachedDashboard?.sites?.length) && !cachedDashboard?.deviceID,
  );
  const [showDeferredDeviceTab, setShowDeferredDeviceTab] = useState(false);

  const user = getUser();
  const scrollRef = useRef(null);

  const persistDashboardCache = useCallback(
    (overrides = {}) => {
      writeDashboardCache({
        selectedSiteIndex: value,
        sites,
        sitesID,
        selectSiteData,
        sitezero,
        deviceID,
        pagination,
        ...overrides,
      });
    },
    [deviceID, pagination, selectSiteData, sitezero, sites, sitesID, value],
  );

  const getdeviceListbysite = useCallback(
    async (siteId, overrides = {}) => {
      if (!siteId) {
        setDevice([]);
        return;
      }

      try {
        setDevicesLoading(true);

        const resp = await GET(API.DEVICE.LIST_BY_SITEID(siteId));
        const nextDevices = Array.isArray(resp?.msg) ? resp.msg : [];

        setDevice(nextDevices);
        setValue1(0);

        persistDashboardCache({
          ...overrides,
          deviceID: nextDevices,
        });
      } catch (error) {
        console.error(error);
        setDevice([]);
      } finally {
        setDevicesLoading(false);
      }
    },
    [persistDashboardCache],
  );

  const getnumberOfSite = useCallback(
    async (page = 1, preferredSiteId = null) => {
      try {
        setSitesLoading(true);

        const resp = await GET(`${API.SITE.COUNT}?page=${page}&limit=10`);

        if (!Array.isArray(resp?.msg)) {
          setSites([]);
          setDevice([]);
          return;
        }

        const nextSites = resp.msg;
        const nextPagination = resp.pagination ?? pagination;
        const selectedSite =
          nextSites.find((site) => site._id === preferredSiteId) ||
          nextSites.find((site) => site._id === sitesID) ||
          nextSites.find((site) => site.deviceCount > 0) ||
          nextSites[0] ||
          null;
        const selectedIndex = selectedSite
          ? nextSites.findIndex((site) => site._id === selectedSite._id)
          : 0;

        setSites(nextSites);
        setPagination(nextPagination);
        setSelectSiteData(selectedSite);
        setSiteZero(selectedSite);
        setSitesID(selectedSite?._id ?? null);
        setValue(selectedIndex >= 0 ? selectedIndex : 0);

        persistDashboardCache({
          sites: nextSites,
          pagination: nextPagination,
          selectSiteData: selectedSite,
          sitezero: selectedSite,
          sitesID: selectedSite?._id ?? null,
          selectedSiteIndex: selectedIndex >= 0 ? selectedIndex : 0,
        });

        if (selectedSite?._id) {
          getdeviceListbysite(selectedSite._id, {
            sites: nextSites,
            pagination: nextPagination,
            selectSiteData: selectedSite,
            sitezero: selectedSite,
            sitesID: selectedSite._id,
            selectedSiteIndex: selectedIndex >= 0 ? selectedIndex : 0,
          });
        } else {
          setDevice([]);
        }
      } catch (error) {
        console.error(error);
      } finally {
        setSitesLoading(false);
      }
    },
    [getdeviceListbysite, pagination, persistDashboardCache, sitesID],
  );

  useEffect(() => {
    getnumberOfSite(cachedDashboard?.pagination?.page ?? 1, cachedDashboard?.sitesID);
  }, [cachedDashboard?.pagination?.page, cachedDashboard?.sitesID, getnumberOfSite]);

  useEffect(() => {
    setShowDeferredDeviceTab(false);

    if (!deviceID?.length || devicesLoading) {
      return undefined;
    }

    if ("requestIdleCallback" in window) {
      const idleId = window.requestIdleCallback(
        () => setShowDeferredDeviceTab(true),
        { timeout: 1200 },
      );

      return () => window.cancelIdleCallback(idleId);
    }

    const timeoutId = window.setTimeout(() => {
      setShowDeferredDeviceTab(true);
    }, 250);

    return () => window.clearTimeout(timeoutId);
  }, [deviceID, devicesLoading]);

  const tabChange = (index) => {
    const selectedSite = sites[index];

    if (!selectedSite) {
      return;
    }

    setValue(index);
    setSelectSiteData(selectedSite);
    setSitesID(selectedSite._id);
    setShowDeferredDeviceTab(false);
    persistDashboardCache({
      selectSiteData: selectedSite,
      sitezero: selectedSite,
      sitesID: selectedSite._id,
      selectedSiteIndex: index,
    });
    getdeviceListbysite(selectedSite._id, {
      selectSiteData: selectedSite,
      sitezero: selectedSite,
      sitesID: selectedSite._id,
      selectedSiteIndex: index,
    });
  };

  const showSiteSkeleton = sitesLoading && sites.length === 0;
  const showEmptySites = !sitesLoading && sites.length === 0;

  return (
    <div className="mx-auto px-4 py-6">
      {showSiteSkeleton ? (
        <>
          <SiteTabsSkeleton />
          <DeviceSectionSkeleton />
        </>
      ) : !showEmptySites ? (
        <>
          <div
            className="rounded-xl p-5 mb-6 bg-gradient-to-r from-[#0a192f] to-[#0f3057]
            shadow-lg border border-[#1f4068]"
          >
            <div className="flex justify-between items-center mb-4">
              <h1 className="text-xl font-semibold text-white">Sites</h1>

              {user?.role !== "user" && user?.role !== "technician" && (
                <Suspense fallback={<LazyActionFallback label="Load add site" />}>
                  <AddSiteDialog
                    getnumberOfSite={getnumberOfSite}
                    buttonClass="px-4 py-1.5 border border-white text-white text-sm font-semibold
                    rounded-lg hover:bg-blue-900 transition-colors duration-200"
                  />
                </Suspense>
              )}
            </div>

            <div className="flex items-center gap-2">
              <div
                ref={scrollRef}
                className="flex-1 flex justify-center gap-2 overflow-x-auto scroll-smooth py-0.5"
                style={{ scrollbarWidth: "none", msOverflowStyle: "none" }}
              >
                {sites.map((site, index) => (
                  <button
                    key={site._id}
                    onClick={() => tabChange(index)}
                    className={`flex-shrink-0 flex items-center gap-6 px-4 py-2 rounded-lg
                    whitespace-nowrap transition-all duration-200 font-medium text-sm ${
                      value === index
                        ? "bg-white text-[#0f3057] shadow-md"
                        : "bg-[#1f4068] text-white hover:bg-[#274c77]"
                    }`}
                  >
                    <span className="max-w-[200px] truncate">{site.siteName}</span>
                    <span
                      className={`text-xs px-2 py-0.5 rounded-full font-semibold flex-shrink-0 ${
                        value === index
                          ? "bg-[#0f3057] text-white"
                          : "bg-white text-[#0f3057]"
                      }`}
                    >
                      {site.deviceCount}
                    </span>
                  </button>
                ))}
              </div>
            </div>

            {pagination.totalPages > 1 && (
              <div className="flex items-center justify-between mt-5 pt-4 border-t border-[#1f4068]">
                <span className="text-sm text-white">
                  Page {pagination.page} of {pagination.totalPages}
                  <span className="ml-2 text-white">({pagination.total} sites total)</span>
                </span>

                <div className="flex items-center gap-2">
                  <button
                    disabled={pagination.page === 1}
                    onClick={() => getnumberOfSite(1, sitesID)}
                    className="px-3 py-1.5 rounded text-sm font-medium border border-[#274c77]
                    text-white disabled:opacity-30 disabled:cursor-not-allowed
                    hover:bg-[#274c77] transition"
                  >
                    First
                  </button>
                  <button
                    disabled={pagination.page === 1}
                    onClick={() => getnumberOfSite(pagination.page - 1, sitesID)}
                    className="px-3 py-1.5 rounded text-sm font-medium border border-[#274c77]
                    text-white disabled:opacity-30 disabled:cursor-not-allowed
                    hover:bg-[#274c77] transition"
                  >
                    Prev
                  </button>
                  <button
                    disabled={pagination.page === pagination.totalPages}
                    onClick={() => getnumberOfSite(pagination.page + 1, sitesID)}
                    className="px-3 py-1.5 rounded text-sm font-medium border border-[#274c77]
                    text-white disabled:opacity-30 disabled:cursor-not-allowed
                    hover:bg-[#274c77] transition"
                  >
                    Next
                  </button>
                </div>
              </div>
            )}
          </div>

          <div className="bg-white rounded-xl shadow border p-5">
            <div className="flex justify-between items-center">
              <h2 className="text-lg font-bold text-[#0f3057]">Devices</h2>

              {user?.role !== "user" && user?.role !== "technician" && (
                <Suspense fallback={<LazyActionFallback label="Load add device" />}>
                  <AddDevice
                    getnumberOfSite={getnumberOfSite}
                    getdeviceListbysite={getdeviceListbysite}
                    state={selectSiteData}
                    sitezero={sitezero}
                    value={value}
                  />
                </Suspense>
              )}
            </div>

            {devicesLoading ? (
              <div className="mt-5">
                <DeviceSectionSkeleton />
              </div>
            ) : deviceID?.length > 0 ? (
              showDeferredDeviceTab ? (
                <Suspense fallback={<div className="mt-5"><DeviceSectionSkeleton /></div>}>
                  <DeviceTab
                    deviceID={deviceID}
                    value1={value1}
                    setValue1={setValue1}
                  />
                </Suspense>
              ) : (
                <div className="mt-5">
                  <DeviceSectionSkeleton />
                </div>
              )
            ) : (
              <div className="flex flex-col items-center justify-center py-16">
                <img
                  src={NodataFound}
                  alt="No Device"
                  width="192"
                  height="144"
                  loading="lazy"
                  decoding="async"
                  className="w-48 opacity-70 h-auto"
                />

                <p className="mt-4 text-gray-600">No Device found</p>

                {user?.role !== "user" && user?.role !== "technician" && (
                  <div className="mt-4">
                    <Suspense fallback={<LazyActionFallback label="Load add device" />}>
                      <AddDevice
                        getnumberOfSite={getnumberOfSite}
                        getdeviceListbysite={getdeviceListbysite}
                        state={selectSiteData}
                        sitezero={sitezero}
                        value={value}
                      />
                    </Suspense>
                  </div>
                )}
              </div>
            )}
          </div>
        </>
      ) : (
        <div className="flex flex-col items-center justify-center h-[80vh]">
          <img
            src={NodataFound}
            alt="No Site"
            width="208"
            height="156"
            loading="lazy"
            decoding="async"
            className="w-52 opacity-70 h-auto"
          />

          <p className="mt-4 text-gray-600">No Site found</p>

          {user?.role !== "user" && user?.role !== "technician" && (
            <div className="mt-4">
              <Suspense fallback={<LazyActionFallback label="Load add site" />}>
                <AddSiteDialog
                  getnumberOfSite={getnumberOfSite}
                  buttonClass="px-5 py-2 bg-blue-400 border border-white-900 text-white
                  text-sm font-semibold bg-blue-800 rounded-lg transition-all duration-200
                  hover:bg-blue-900 hover:text-white"
                />
              </Suspense>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

export default App;
